            "username": username,
            "notes": notes,
            "edition_id": edition_id,
        }
        records = cls.get_patron_booknotes(
            username, work_id=work_id, edition_id=edition_id
        )
        if not records:
            return oldb.insert(
                'booknotes',
                username=username,
                work_id=work_id,
                notes=notes,
                edition_id=edition_id,
            )
        return oldb.update(
            'booknotes',
            where="work_id=$work_id AND username=$username AND edition_id=$edition_id",
            notes=notes,
            edition_id=edition_id,
            vars=data,
        )

